from collections.abc import Mapping
from copy import deepcopy


def _record(value):
    if not isinstance(value, Mapping):
        raise TypeError("records must be mappings")
    if set(value) != {"namespace", "commands", "metadata"}:
        raise ValueError("record keys are invalid")
    namespace = value["namespace"]
    if not isinstance(namespace, str):
        raise TypeError("namespace must be a string")
    if not namespace.strip():
        raise ValueError("namespace cannot be empty")
    commands = value["commands"]
    if isinstance(commands, (str, bytes)):
        raise TypeError("commands must be a non-string iterable")
    try:
        iterator = iter(commands)
    except TypeError:
        raise TypeError("commands must be a non-string iterable") from None
    normalized = []
    seen = set()
    for command in iterator:
        if not isinstance(command, str):
            raise TypeError("commands must be strings")
        if not command.strip():
            raise ValueError("commands cannot be empty")
        if command in seen:
            raise ValueError("commands must be unique")
        seen.add(command)
        normalized.append(command)
    if not isinstance(value["metadata"], dict):
        raise TypeError("metadata must be a dictionary")
    return {
        "namespace": namespace,
        "commands": tuple(normalized),
        "metadata": deepcopy(value["metadata"]),
    }


def compose_command_catalog(sections, fallback):
    result = [{"namespace": "system", "commands": ("help",), "metadata": {}}]
    namespaces = {"system"}
    try:
        iterator = iter(sections)
    except TypeError:
        raise TypeError("sections must be iterable") from None
    for section in iterator:
        record = _record(section)
        if record["namespace"] in namespaces:
            raise ValueError("duplicate namespace")
        namespaces.add(record["namespace"])
        result.insert(1, record)
    final = _record(fallback)
    if final["namespace"] in namespaces:
        raise ValueError("duplicate namespace")
    result.append(final)
    return tuple(result)

